#[allow(dead_code)]
mod common;
#[allow(unused_imports)]
use common::{distinct, equal, ordered};
use std::ops::{Add, Neg, Sub};
use timetuck::HardMediumSoftScore;

#[test]
fn of() {
    assert_eq!(
        HardMediumSoftScore::of_hard(-147),
        HardMediumSoftScore::new(-147, 0, 0)
    );
    assert_eq!(
        HardMediumSoftScore::of_medium(-258),
        HardMediumSoftScore::new(0, -258, 0)
    );
    assert_eq!(
        HardMediumSoftScore::of_soft(-369),
        HardMediumSoftScore::new(0, 0, -369)
    );
}

#[test]
fn parse_score() {
    assert_eq!(
        "-147hard/-258medium/-369soft"
            .parse::<HardMediumSoftScore>()
            .unwrap(),
        HardMediumSoftScore::new(-147, -258, -369)
    );
    assert_eq!(
        "-147hard/-258medium/*soft"
            .parse::<HardMediumSoftScore>()
            .unwrap(),
        HardMediumSoftScore::new(-147, -258, i64::MIN)
    );
    assert_eq!(
        "-147hard/*medium/-369soft"
            .parse::<HardMediumSoftScore>()
            .unwrap(),
        HardMediumSoftScore::new(-147, i64::MIN, -369)
    );
    assert_eq!(
        "-1structural/0hard/0medium/0soft"
            .parse::<HardMediumSoftScore>()
            .unwrap(),
        HardMediumSoftScore::new(0, 0, 0).with_structural(-1)
    );
}

#[test]
fn to_short_string() {
    assert_eq!(HardMediumSoftScore::new(0, 0, 0).to_short_string(), "0");
    assert_eq!(
        HardMediumSoftScore::new(0, 0, -369).to_short_string(),
        "-369soft"
    );
    assert_eq!(
        HardMediumSoftScore::new(0, -258, 0).to_short_string(),
        "-258medium"
    );
    assert_eq!(
        HardMediumSoftScore::new(0, -258, -369).to_short_string(),
        "-258medium/-369soft"
    );
    assert_eq!(
        HardMediumSoftScore::new(-147, -258, -369).to_short_string(),
        "-147hard/-258medium/-369soft"
    );
    assert_eq!(
        HardMediumSoftScore::new(-147, -258, -369)
            .with_structural(-1)
            .to_short_string(),
        "-1structural/-147hard/-258medium/-369soft"
    );
}

#[test]
fn test_to_string() {
    assert_eq!(
        (HardMediumSoftScore::new(0, -258, -369)).to_string(),
        "0hard/-258medium/-369soft"
    );
    assert_eq!(
        (HardMediumSoftScore::new(-147, -258, -369)).to_string(),
        "-147hard/-258medium/-369soft"
    );
    assert_eq!(
        (HardMediumSoftScore::new(-147, -258, -369).with_structural(-1)).to_string(),
        "-1structural/-147hard/-258medium/-369soft"
    );
}

#[test]
fn parse_score_illegal_argument() {
    assert!("-147".parse::<HardMediumSoftScore>().is_err());
    assert!("-1structural/0hard".parse::<HardMediumSoftScore>().is_err());
}

#[test]
fn feasible() {
    assert!(!(HardMediumSoftScore::new(-5, -300, -4000)).is_feasible());
    assert!(!(HardMediumSoftScore::new(0, 0, 0).with_structural(-1)).is_feasible());
    assert!((HardMediumSoftScore::new(0, -300, -4000)).is_feasible());
    assert!((HardMediumSoftScore::new(2, -300, -4000)).is_feasible());
}

#[test]
fn add() {
    assert_eq!(
        HardMediumSoftScore::new(20, -20, -4000).add(HardMediumSoftScore::new(-1, -300, 4000)),
        HardMediumSoftScore::new(19, -320, 0)
    );
}

#[test]
fn subtract() {
    assert_eq!(
        HardMediumSoftScore::new(20, -20, -4000).sub(HardMediumSoftScore::new(-1, -300, 4000)),
        HardMediumSoftScore::new(21, 280, -8000)
    );
}

#[test]
fn multiply() {
    assert_eq!(
        HardMediumSoftScore::new(5, -5, 5).multiply(1.2),
        HardMediumSoftScore::new(6, -6, 6)
    );
    assert_eq!(
        HardMediumSoftScore::new(1, -1, 1).multiply(1.2),
        HardMediumSoftScore::new(1, -2, 1)
    );
    assert_eq!(
        HardMediumSoftScore::new(4, -4, 4).multiply(1.2),
        HardMediumSoftScore::new(4, -5, 4)
    );
}

#[test]
fn divide() {
    assert_eq!(
        HardMediumSoftScore::new(25, -25, 25).divide(5.0),
        HardMediumSoftScore::new(5, -5, 5)
    );
    assert_eq!(
        HardMediumSoftScore::new(21, -21, 21).divide(5.0),
        HardMediumSoftScore::new(4, -5, 4)
    );
    assert_eq!(
        HardMediumSoftScore::new(24, -24, 24).divide(5.0),
        HardMediumSoftScore::new(4, -5, 4)
    );
}

#[test]
fn power() {
    assert_eq!(
        HardMediumSoftScore::new(3, -4, 5).power(2.0),
        HardMediumSoftScore::new(9, 16, 25)
    );
    assert_eq!(
        HardMediumSoftScore::new(9, 16, 25).power(0.5),
        HardMediumSoftScore::new(3, 4, 5)
    );
}

#[test]
fn negate() {
    assert_eq!(
        HardMediumSoftScore::new(3, -4, 5).neg(),
        HardMediumSoftScore::new(-3, 4, -5)
    );
    assert_eq!(
        HardMediumSoftScore::new(-3, 4, -5).neg(),
        HardMediumSoftScore::new(3, -4, 5)
    );
}

#[test]
fn abs() {
    assert_eq!(
        HardMediumSoftScore::new(3, 4, 5).abs(),
        HardMediumSoftScore::new(3, 4, 5)
    );
    assert_eq!(
        HardMediumSoftScore::new(3, -4, 5).abs(),
        HardMediumSoftScore::new(3, 4, 5)
    );
    assert_eq!(
        HardMediumSoftScore::new(-3, 4, -5).abs(),
        HardMediumSoftScore::new(3, 4, 5)
    );
    assert_eq!(
        HardMediumSoftScore::new(-3, -4, -5).abs(),
        HardMediumSoftScore::new(3, 4, 5)
    );
}

#[test]
fn zero() {
    assert_eq!(HardMediumSoftScore::ZERO, HardMediumSoftScore::new(0, 0, 0));
    assert!(HardMediumSoftScore::ZERO.is_zero());
    assert!(!HardMediumSoftScore::new(0, 0, 1).is_zero());
}

#[test]
fn equals_and_hash_code() {
    equal(&[
        HardMediumSoftScore::new(-10, -200, -3000),
        HardMediumSoftScore::new(-10, -200, -3000),
    ]);
    equal(&[
        HardMediumSoftScore::new(-10, -200, -3000).with_structural(-1),
        HardMediumSoftScore::new(-10, -200, -3000).with_structural(-1),
    ]);
    distinct(&[
        HardMediumSoftScore::new(-10, -200, -3000),
        HardMediumSoftScore::new(-30, -200, -3000),
        HardMediumSoftScore::new(-10, -400, -3000),
        HardMediumSoftScore::new(-10, -400, -5000),
        HardMediumSoftScore::new(-10, -200, -3000).with_structural(-1),
    ]);
}

#[test]
fn compare_to() {
    ordered(&[
        HardMediumSoftScore::new(-20, i64::MIN, i64::MIN).with_structural(-1),
        HardMediumSoftScore::new(-20, i64::MIN, i64::MIN),
        HardMediumSoftScore::new(-20, i64::MIN, -20),
        HardMediumSoftScore::new(-20, i64::MIN, 1),
        HardMediumSoftScore::new(-20, -300, -4000),
        HardMediumSoftScore::new(-20, -300, -300),
        HardMediumSoftScore::new(-20, -300, -20),
        HardMediumSoftScore::new(-20, -300, 300),
        HardMediumSoftScore::new(-20, -20, -300),
        HardMediumSoftScore::new(-20, -20, 0),
        HardMediumSoftScore::new(-20, -20, 1),
        HardMediumSoftScore::new(-1, -300, -4000),
        HardMediumSoftScore::new(-1, -300, -20),
        HardMediumSoftScore::new(-1, -20, -300),
        HardMediumSoftScore::new(1, i64::MIN, -20),
        HardMediumSoftScore::new(1, -20, i64::MIN),
    ]);
}
